#include "stdafx.h"

// =============================================================================
//  (th4) UKRAINIAN localization (LANG_UK, language 15).
//  Mirrors LocalizationBG.cpp (the other Cyrillic language) structurally and
//  LocalizationNL.cpp (the newest scaffold) procedurally.
//
//  ENCODING: raw CP1251 bytes as \xNN escapes, file read/written latin-1.
//  Rides the RUSSIAN font path (Codepage_Cyrillic + FontIndex*_Cyrillic CELs,
//  DLL atlas CP1251-0x40 for meta-menu captions and trait strings) -- see the
//  LANG_UK case in InitLocalization() and TraitAtlasToCP1251() in Perks.cpp.
//
//  THE SUBSTITUTION CONVENTION (option 2, approved by Mordor 2026-08-26):
//  the Cyrillic CEL frames and the ui_art atlas contain only the 32 Russian
//  letters. The four Ukrainian-only letters are therefore written with
//  look-alikes AT TRANSLATION TIME:
//
//      wanted            write instead        bytes
//      -----------       -------------        --------------------------
//      i  (U+0456)       Latin i / I          0x69 / 0x49
//      yi (U+0457)       Latin i / I          0x69 / 0x49   (diaeresis dropped)
//      ye (U+0454)       \xE5 / \xC5          Cyrillic E    (E-sound kept)
//      g-uphook (U+0491) \xE3 / \xC3          Cyrillic G    (rare letter)
//      apostrophe (\')   0x27                 plain ASCII apostrophe
//
//  NEVER emit the CP1251 Ukrainian codepoints \xA5 \xAA \xAF \xB2 \xB3 \xB4
//  \xBA \xBF -- the fonts have no frames there and the text would draw BLANK.
//  dataseg.cpp maps Latin I/i (0x49/0x69) to frame 27 in the BIG and MID
//  Cyrillic index tables, and 0x27 to frame 47 in the MID table, so the
//  substitutes and the apostrophe render in every font the game uses.
//
//  RULES (same as BG):
//    * Overlay tables below hold REAL CP1251 bytes (no atlas offset), EXCEPT
//      UK_Menu, which is ATLAS-encoded (CP1251 - 0x40) like RU MenuStrings.
//    * \xNN followed by a literal hex digit char needs a "" break (C2022
//      greedy-hex trap).
//    * A missing key falls back to ENGLISH. Partial Ukrainian is safe to ship.
//    * Keys must byte-exactly match the English source literal.
// =============================================================================

struct UiStr  { const char* en; const char* uk; };
struct IdxStr { int index; const char* uk; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	// (th4) MUST stay in sync with the master enum in Localization.cpp -- ids are shared
	// array indices. Appended last, so 0..14 are unchanged for every other loc file.
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };


