// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr& r )  { return r.en == 0 && r.uk == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index == 0 && r.uk == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* UK_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(UK_Ui);           return UK_Ui;
		case OVL_MENU:          *n = countRows(UK_Menu);         return UK_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(UK_UniqueItem);   return UK_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(UK_AffixPrefix);  return UK_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(UK_AffixSuffix);  return UK_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(UK_BaseItem);     return UK_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(UK_BaseName2);    return UK_BaseName2;
		case OVL_ELEMENT:       *n = countRows(UK_Element);      return UK_Element;
		case OVL_SPICIES:       *n = countRows(UK_Spicies);      return UK_Spicies;
		case OVL_ICEAGE:        *n = countRows(UK_IceAge);       return UK_IceAge;
		case OVL_SPELL:         *n = countRows(UK_Spell);        return UK_Spell;
		case OVL_SPELL_NOM:     *n = countRows(UK_SpellNom);     return UK_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(UK_PerkName);     return UK_PerkName;
		case OVL_PERK_DESC:     *n = countRows(UK_PerkDesc);     return UK_PerkDesc;
		case OVL_WARP:          *n = countRows(UK_Warp);         return UK_Warp;
		case OVL_WARP_OBL:      *n = countRows(UK_WarpOblique);  return UK_WarpOblique;
	}
	*n = 0; return 0;
}

const IdxStr* UK_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(UK_Speech);     return UK_Speech;
		case OVL_ONSCREEN:  *n = countRows(UK_OnScreen);   return UK_OnScreen;
		case OVL_QUEST:     *n = countRows(UK_Quest);      return UK_Quest;
	}
	*n = 0; return 0;
}
